<?php if(!defined('ABSPATH'))exit;if($role!=='admin'){echo '<p>Access denied.</p>';return;} global $wpdb;$t=$wpdb->prefix.'rp_cash_shifts';$open=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE status='open' ORDER BY id DESC LIMIT 1"));$rows=$wpdb->get_results("SELECT s.*,u.display_name FROM $t s LEFT JOIN {$wpdb->users} u ON u.ID=s.user_id ORDER BY s.id DESC LIMIT 50");?>
<h1 class="page-title">Cash Shift & Day Closing</h1><?php if(!$open):?><div class="p-card"><h3 class="p-card-title mb-12">Open Cash Shift</h3><form method="post"><?php wp_nonce_field('rp_shift_action');?><input type="hidden" name="rp_shift_action" value="open"><input class="form-input" name="opening_cash" type="number" step="0.01" min="0" required placeholder="Opening cash (Rs.)"><button class="btn btn-primary" type="submit">Open Shift</button></form></div><?php else:?><div class="p-card" style="border:2px solid #22c55e"><h3 class="p-card-title">Current Open Shift</h3><p>Opened with <strong>Rs. <?php echo number_format((float)$open->opening_cash,2);?></strong> on <?php echo esc_html(wp_date('d M Y g:i A',strtotime($open->opened_at)));?></p><form method="post"><?php wp_nonce_field('rp_shift_action');?><input type="hidden" name="rp_shift_action" value="close"><input type="hidden" name="shift_id" value="<?php echo (int)$open->id;?>"><input class="form-input" name="actual_cash" type="number" step="0.01" min="0" required placeholder="Actual cash counted (Rs.)"><textarea class="form-input" name="notes" placeholder="Closing notes"></textarea><button class="btn btn-primary" type="submit">Close Day</button></form></div><?php endif;?><div class="p-card"><h3 class="p-card-title mb-12">Shift History</h3><?php foreach($rows as $r):?><div class="order-item"><span class="order-num"><?php echo esc_html(wp_date('d M',strtotime($r->shift_date)));?></span><div class="order-meta"><strong><?php echo esc_html($r->display_name?:'Staff');?></strong><span class="text-sm text-muted"><?php echo esc_html(ucfirst($r->status));?> • Expected Rs. <?php echo number_format((float)$r->expected_cash,2);?> • Actual Rs. <?php echo number_format((float)$r->actual_cash,2);?></span></div><strong><?php echo number_format((float)$r->difference,2);?></strong></div><?php endforeach;?></div>